  if(!ready.length)continue;
  row.visible=true;motionVisible=true;state.motion.actors+=row.actors.cars.length;
  actorCanvas??=document.createElement('canvas');actorContext??=actorCanvas.getContext('2d');
  actorCanvas.width=canvas.width;actorCanvas.height=canvas.height;actorContext.setTransform(dpr,0,0,dpr,0,0);
  const visibleCars=row.actors.cars.filter(car=>actorVisibleByMask(car,data.projection,c.projected_rect_m,row.visibilityMask));state.motion.visibleCars+=visibleCars.length;
  state.motion.samples.push(...visibleCars.slice(0,2).map(car=>({canvas_id:c.id,actor_index:row.actors.cars.indexOf(car),distance:car.distance,x:car.x,y:car.y,z:car.z,visible:true})));
  drawRoadActors(actorContext,{cars:visibleCars},data.projection,point,lighting.night);
  const rect=c.projected_rect_m,tl=point([rect[0],rect[3]]),br=point([rect[2],rect[1]]);
  actorContext.globalCompositeOperation='destination-in';actorContext.imageSmoothingEnabled=false;actorContext.drawImage(row.mask,tl[0],tl[1],br[0]-tl[0],br[1]-tl[1]);actorContext.globalCompositeOperation='source-over';
  // Never draw over absent, held, failed or not-yet-loaded artwork, even when a
