function programmesFor(ids){return data.activities.filter(a=>a.venue_ids.some(id=>ids.includes(id)));}
function select(f,{move=true}={}){selected=f;hovered=null;$('map-tooltip').hidden=true;if(move){if(f.bounds){fitBounds(f.bounds.map((n,i)=>n+(i<2?-55:55)));}else{camera.x=f.point[0];camera.y=f.point[1];camera.scale=Math.max(camera.scale,.25);}}if(f.kind==='place')renderPlace(f);else renderFeature(f);openPanel('place-panel');$('place-panel').focus({preventScroll:true});$('search-results').hidden=true;document.querySelectorAll('[data-featured]').forEach(b=>b.setAttribute('aria-current',b.dataset.featured===f.id));history.replaceState(null,'',`#place=${encodeURIComponent(f.id)}`);announce(f.name+'. Same geographic map, not a separate picture view.');invalidate();}
function renderPlace(p){const own=programmesFor(p.venue_ids),gate=manifest.landmark_gates?.find(g=>g.place_id===p.id&&g.status!=='accepted');let html=`<span class="badge">${esc(kindNames[p.category])}</span><h2>${esc(p.name)}</h2><div class="place-meta">${p.wgs84[1].toFixed(4)}° N, ${Math.abs(p.wgs84[0]).toFixed(4)}° W · Geographic destination</div>`;if(gate)html+=`<p class="notice">${esc(gate.reason)}</p>`;if(own.length)html+=`<h3 class="programme-group">At this source venue · ${own.length} saved listings</h3><p class="sample-note">Saved ${esc(dateText(data.coverage.fetched_at))}. Not live availability; unknown fees and facts remain unknown.</p>`+own.map(a=>programmeCard(a,venueById,{showVenue:false})).join('');else html+=`<div class="empty-state">${p.category==='hotspot'?'A hotspot is not automatically a City programme venue.':p.category==='context'?'No programme venue is assigned to this landscape.':'No detailed programme sample was captured for this venue.'} This does not mean activities are unavailable.</div>`;html+='<p class="source-stamp">Final eligibility, availability, fees, consent, registration and payment remain entirely on the official City site. This candidate performs no enrollment.</p>';$('place-content').innerHTML=html;}
function renderFeature(f){const source=f.source||{},proposal=f.display_component==='proposal';$('place-content').innerHTML=`<span class="badge">${esc(f.kind==='facility'?'Facility / POI record':layersLabel(f.layer))}</span><h2>${esc(f.name)}</h2><p>${esc(f.id)}</p>${f.address?`<p>${esc(f.address)}</p>`:'<p>Address not supplied in this map record.</p>'}${f.display_facility_type?`<p>${proposal?'Proposed, not built':'Existing component'}: ${esc(f.display_facility_type)}</p>`:''}${f.existing?.mapped?`<p>Present facility: ${esc(f.existing.facility_type||'Type unknown')}</p>`:''}${f.proposal?.mapped?`<p>Future proposal: ${esc(f.proposal.facility_type||'Type unknown')}. Not a built-route claim.</p>`:''}<p class="notice">${f.layer==='natural'?'Dated 2021 natural-area geography. A natural linkage is not a trail or evidence of public access. ':''}Current access, closures and bookability are unknown. ${f.kind==='facility'?'A facility source record is not a verified current programme venue.':''} This is not a navigation or trail-safety map.</p><p>Official source: ${esc(source.dataset||'Unknown')}, layer ${esc(source.layer_id??'Unknown')}, object ${esc(source.object_id??'Unknown')}. ${source.data_last_edit_utc?'Reported edit '+esc(dateText(source.data_last_edit_utc))+'.':''}</p>${sourceLink(source.layer_url)}<p class="source-stamp">Source-qualified records are not automatically merged into distinct sites. Geography is displayed on the same fixed camera; terrain outside the source DEM footprint is unavailable, not assumed flat.</p>`;}
function sourceLink(url){try{const u=new URL(url);if(u.protocol==='https:'&&u.hostname==='services6.arcgis.com'&&/^\/hM5ymMLbxIyWTjn2\/arcgis\/rest\/services\/[\w/]+\/FeatureServer\/\d+$/.test(u.pathname))return `<a href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">Official layer metadata ↗</a>`;}catch{}return '';}
const labels={places:'Selected geographic places',parks:'Park boundaries',natural:'Natural areas · 2021','cycling-existing':'Existing cycling','cycling-proposed':'Proposed cycling',facilities:'Facility / POI records'};
