function renderProgrammes(){const q=$('programme-search').value.trim().toLowerCase(),today=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Toronto',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());const items=data.activities.filter(a=>{const names=a.venue_ids.map(id=>venueById.get(id)?.name||'').join(' ');if(q&&!`${a.name} ${names}`.toLowerCase().includes(q))return false;const s=$('schedule-filter').value;if(s==='known'&&!a.schedule)return false;if(s==='future'&&(!a.schedule?.date_start||a.schedule.date_start<today))return false;const known=a.price?.from_amount!==null&&a.price?.from_amount!==undefined;return !($('fee-filter').value==='known'&&!known||$('fee-filter').value==='unknown'&&known);});$('programme-count').textContent=`${items.length} of ${data.activities.length} saved listings · ${data.coverage.captured_full_list_items} detailed, the rest partial teasers`;$('programme-list').innerHTML=items.length?items.map(a=>programmeCard(a,venueById)).join(''):'<p class="no-results">No saved records match. This is an incomplete sample; unknown does not mean unavailable.</p>';}
