let dataRenderToken=0;
async function renderData(){const token=++dataRenderToken,id=$('data-category').value,q=$('data-search').value.trim().toLowerCase();$('data-count').textContent='Loading actual source records…';let rows;try{rows=id==='places'?data.places:await loadLayer(id);}catch{$('data-count').textContent='Source data could not load. Select another category to retry.';return;}if(token!==dataRenderToken)return;rows=rows.filter(f=>!q||`${f.name} ${f.id} ${f.display_facility_type||''}`.toLowerCase().includes(q));$('data-count').textContent=`${rows.length.toLocaleString('en-CA')} source records · ${layersLabel(id)}`;$('data-list').innerHTML=rows.slice(0,dataLimit).map((f,i)=>`<button class="data-row" data-row="${i}">${esc(f.name)}<small>${esc(f.id)}${f.display_facility_type?' · '+esc(f.display_facility_type):''}${id==='cycling-proposed'?' · Not built':''}</small></button>`).join('')||'<p class="no-results">No matching source record.</p>';$('data-list').querySelectorAll('[data-row]').forEach(b=>b.onclick=()=>{if(id!=='places'){active.add(id);document.querySelector(`[data-layer="${id}"]`).checked=true;}select(rows[Number(b.dataset.row)]);});$('data-more').hidden=rows.length<=dataLimit;}
function openData(id='places',q=''){openPanel('data-panel');$('data-category').value=id;$('data-search').value=q;dataLimit=80;renderData();$('data-search').focus();}
function renderSearch(){const q=$('search').value.trim().toLowerCase();$('search-clear').hidden=!q;if(!q){$('search-results').hidden=true;return;}const hits=[...data.places,...available('facilities'),...available('parks'),...available('natural'),...available('cycling-existing'),...available('cycling-proposed')].filter(p=>p.name.toLowerCase().includes(q)).slice(0,20),acts=data.activities.filter(a=>a.name.toLowerCase().includes(q)).slice(0,4);$('search-results').innerHTML=hits.map((p,i)=>`<button class="result-row" data-hit="${i}">${esc(p.name)}<small>${esc(p.kind==='place'?kindNames[p.category]:layersLabel(p.layer))}${p.display_component==='proposal'?' · Not built':''}</small></button>`).join('')+acts.map((a,i)=>`<button class="result-row" data-programme="${i}">${esc(a.name)}<small>Saved programme · not live availability</small></button>`).join('')+'<button class="result-row" id="search-all-data">Search all source records by category<small>Includes lazy-loaded facility and natural-area records</small></button>';$('search-results').hidden=false;$('search-results').querySelectorAll('[data-hit]').forEach(b=>b.onclick=()=>select(hits[Number(b.dataset.hit)]));$('search-results').querySelectorAll('[data-programme]').forEach(b=>b.onclick=()=>openBrowse(acts[Number(b.dataset.programme)].name));$('search-all-data').onclick=()=>{const query=$('search').value;$('search-results').hidden=true;openData('facilities',query);};}
function hitAt(x,y){const markers=[...hitTargets].reverse().find(h=>Math.hypot(h.x-x,h.y-y)<14);if(markers)return markers.feature;const p=world([x,y]);ctx.save();ctx.setTransform(1,0,0,1,0,0);ctx.lineWidth=14/camera.scale;for(const id of ['cycling-proposed','cycling-existing','natural','parks']){if(!active.has(id))continue;const padding=14/camera.scale;for(const f of available(id)){if(!intersects([p[0]-padding,p[1]-padding,p[0]+padding,p[1]+padding],f.bounds))continue;const yes=id.startsWith('cycling')?ctx.isPointInStroke(f.path,...p):ctx.isPointInPath(f.path,...p,'evenodd');if(yes){ctx.restore();return f;}}}ctx.restore();return null;}
function showSources(){if(referenceConfig){$('info-content').innerHTML='<h2>Private teacher reference, not a trained model</h2><p>One actual registered Absolute World teacher, exact native896 crop [64,64,960,960]. The new UTM26917 block and common Ontario DTM reference are explicit and are not aliased to the older Mapzen city frame. Research visual review is not production geography, training acceptance or model acceptance.</p><p>Cars reuse actual source-viewer meshes and road motion. Their fragments are tested against actual captured source depth in the exact crop. Only complete actors inside an additionally reviewed registered-raster road corridor appear. Buildings, road drift, vegetation and unknown segments elsewhere remain withheld. This is simulated ambience, not live traffic.</p><p>The original solar/DST clock and compositor drive this teacher image without regeneration. Current fixed-Mississauga Open-Meteo model weather is dated and cached; time previews retain current weather. '+(referenceConfig.window_emission_review?'The automatic per-final-tile mask clips inferred light cells to actual source-visible facades, finite source depth and actual painted glass/contrast texture, including curved towers and small buildings. These cells are simulated illumination, NOT detected physical windows or people. Actual source feature identities and reconstructed UTM/elevation world cells seed stable occupancy across tiles and camera changes. A single cached RGB mask is sampled by the existing shader; there are no per-window light objects, training-pair requirement or image calls. Roofs, roads, water, ground and all streetlight pools emit nothing.':'No verified window mask is bound, so night demonstrates grading only, without invented window or streetlight-pool emission.')+'</p><p>Source attribution: City of Mississauga open massing, OPEN street centrelines and planimetric surfaces; Ontario DTM common source reference, not survey-grade road decks. <a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">Open-Meteo model weather</a> under CC BY 4.0. <a href="lighting/LICENSE-TORONTO.txt" target="_blank" rel="noopener noreferrer">MIT lighting software attribution</a>.</p><p>All reference images, depth and source mounts are localhost-only and outside public/. No production acceptance, deployment, image/model calls, credentials, account changes or location tracking.</p>';if(referenceConfig.window_emission_review?.partial_coverage)$('info-content').insertAdjacentHTML('beforeend','<p><strong>Partial lighting coverage:</strong> Curved Absolute World source72/6104 is fully held and emits nothing. Only the retained flat/rotated inferred native-UV room cells are enabled. This is not a physical pane inventory, a global curve-quality pass or final visual acceptance. No bloom or streetlight pools.</p>');$('info-dialog').showModal();return;}if(manifest.canvases.some(c=>c.kind==='genuine-citywide-mosaic')){$('info-content').innerHTML=`<h2>The whole city, in miniature.</h2><p>Little Mississauga is a RollerCoaster Tycoon 3–style map of the entire city. Every building comes from the City's published 3D massing, every hill from the Province's terrain model, and every road, park and creek from municipal map data. A small fine-tuned image model repaints it all as one continuous miniature.</p><p>The sky follows real Toronto time and a live weather estimate. After dark, windows light up and simulated traffic drives the real street network with its headlights on.</p><p><a href="how.html">How it was made →</a> &nbsp;·&nbsp; <a href="https://github.com/moeealii/little-mississauga" target="_blank" rel="noopener noreferrer">Source on GitHub</a></p><h3>Good to know</h3><ul><li>The artwork is illustrative, not a survey. The buildings and roads are real; their paint is imagined.</li><li>Traffic and lit windows are simulated, not live.</li><li>A few City Centre blocks are shown from separately reviewed renders while their landmark details are checked.</li><li>Programme listings are a November 2026 snapshot. The City's own pages are authoritative for times, fees and registration.</li></ul><h3>Data and credits</h3><p>City of Mississauga Open Data (3D massing, planimetrics, street centrelines, parks, cycling, programmes) · Ontario Digital Terrain Model · Natural Earth · <a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">Open-Meteo</a> (CC BY 4.0). Artwork made with Qwen-Image under its research licence (<a href="LICENSE-QWEN.txt" target="_blank">licence</a>, <a href="NOTICE.txt" target="_blank">notice</a>). Inspired by <a href="https://iso.sloptoronto.ca/how" target="_blank" rel="noopener noreferrer">Slop Toronto</a> and Tiny Toronto; no assets from either.</p><h3>Privacy</h3><p>No accounts, tracking, analytics or location access. Weather is fetched for fixed Mississauga coordinates.</p><p class="source-stamp">Independent noncommercial project, not affiliated with the City of Mississauga.</p>`;$('info-dialog').showModal();return;}$('info-content').innerHTML=`<h2>One geographic canvas.<br>Honest limits.</h2><p>${manifest.model_release?.kind==='genuine-fresh-trained-model'&&manifest.canvases.some(c=>c.acceptance?.status==='accepted')?'This is an independent noncommercial research demonstration with individually reviewed fresh-model study areas. It is not an official City service, a survey, or completed citywide artwork.':'This frontend contains source-data context; fresh model artwork remains pending.'} Dragging, zooming, choosing a destination and fitting the city always use the same world coordinates. Coverage is partial; unavailable art is never filled with unrelated teacher plates or synthetic city. Programme facts are dated, official availability and access must be checked, and simulated cars or inferred window lighting do not report actual traffic or occupants.</p><h3>Architectural acceptance comes first</h3><p>${esc((manifest.landmark_gates||[]).filter(g=>g.status!=='accepted').map(g=>g.reason).join(' ')||'Each visible canvas still requires explicit architecture and coverage review.')} Diagnostic model output is not accepted artwork. Each registered canvas must have explicit coverage and landmark acceptance before appearing here. A passed image hash or dimensions is not visual acceptance.</p><h3>Source geography and terrain</h3><p>Official city boundary and ${data.places.length} selected places; ${data.counts.facilities.toLocaleString('en-CA')} facility/POI records are not distinct sites or verified current programme venues. Parks: 718 source polygons, reported edit August 21, 2024. Natural areas: 358 dated <strong>2021</strong> NAS/linkage/special-management source polygons, reported edit June 29, 2022. Natural linkages are not trails. Cycling: 685 existing components and 621 proposal components from 1,238 source lines, reported edit November 1, 2026. The present and future facilities on upgrade records remain separate. Proposed is not built; access and current closures remain unknown.</p><p>The licence-unresolved 9,197-record pedestrian network and restricted 2024 NAS are not in this public bundle. No inferred connections, walking/biking permissions or route safety claims. Source geometry is projected through the canonical 30° pitch, 45° heading orthographic camera. ${esc(data.projection.terrain_note)} No citywide heights, surveyed grades, bridge decks or grass-wear paths are invented.</p><h3>Toronto local time, registered emission only</h3><p>Automatic lighting uses actual America/Toronto time, IANA DST rules and solar twilight, refreshed every 30 seconds while visible. Day/night modes and local-hour previews are labelled separately. Moving the local-hour slider returns to automatic solar lighting so a noon preview does not remain stuck in forced night. The preview uses the current Toronto local date, not a fixed UTC offset. Windows require artwork-aligned RGB masks: R coverage, G threshold × R, B explicit streetlight pools. Missing or rejected masks emit nothing. No bright-pixel inference, random lamps or claimed streetlight inventory. Window occupancy is illustrative, not actual household activity. Grass wear belongs to accepted source-aligned artwork, not new trails or emissive ground.</p><h3>Fixed-city weather, not location tracking</h3><p><a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">Open-Meteo</a> supplies a public no-key current model estimate for fixed Mississauga coordinates, credited under <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a>. This is not a weather-station observation, real-time street conditions or a safety forecast. The browser sends ordinary network metadata to that provider, never user GPS or accounts. Estimates are cached in memory, refreshed at most every 15 minutes while visible, with explicit manual refresh. Model timestamps older than 90 minutes or a failed refresh are stale; unavailable/unknown/stale conditions produce neutral effects, not guessed weather. Current-weather cloud grading, wet registered pools and restrained rain/snow apply only to verified visible artwork; they create no emission masks or road depth. Time previews keep clearly labelled current weather rather than inventing historical conditions. No image generation is used for time or weather changes.</p><h3>Programme evidence, not promises</h3><p>Official sample saved ${esc(dateText(data.coverage.fetched_at))}: ${data.activities.length} unique records, ${data.coverage.captured_full_list_items} detailed; the rest partial teasers. Source total ${data.coverage.source_total_matching_listings.toLocaleString('en-CA')} matching listings is not open-class count. The list/map count discrepancy of ${data.coverage.list_map_count_difference_unexplained} remains unexplained. Missing fees, ages, schedules, eligibility and availability stay unknown. All registration and consent remain on official City detail pages.</p><h3>Private and quiet by design</h3><p>No accounts, enrollment, cart, consent, payment, analytics, GPS, model service, inference API or model downloads. No browser storage. Model weights, source meshes, raw provenance, credentials and private paths are not bundled. Rendering is demand-driven, with a 30-second clock. Brief lighting transitions and independently moving cars animate only when needed; hidden tabs pause without catching up. Reduced-motion preference makes lighting immediate and starts cars paused. Cars require accepted actor-free artwork, exact source-bound road/height plans and reviewed full car-volume visibility masks. The actual source-viewer motion sampler and car footprint are reused. No routes, actor alignment, road elevations or depth are inferred from teacher imagery; semantic road masks are not depth. Missing bindings withhold cars, not replace the city with a mock scene. No Toronto map assets or game assets copied.</p><ul><li><a href="NOTICE.txt" target="_blank" rel="noopener noreferrer">Source credits and research notice</a> · <a href="LICENSE-QWEN.txt" target="_blank" rel="noopener noreferrer">Qwen research licence</a></li><li><a href="lighting/LICENSE-TORONTO.txt" target="_blank" rel="noopener noreferrer">MIT lighting software licence</a> · <a href="https://iso.sloptoronto.ca/how" target="_blank" rel="noopener noreferrer">Lighting methodology reference</a></li><li><a href="https://www.mississauga.ca/our-organization/data-and-maps/open-data-catalogue/" target="_blank" rel="noopener noreferrer">City open data catalogue</a> · <a href="https://www.mississauga.ca/file/COM/CityOfMississaugaTermsOfUse.pdf" target="_blank" rel="noopener noreferrer">City source-data terms</a></li><li><a href="https://www.mississauga.ca/publication/open-data-program-policy/" target="_blank" rel="noopener noreferrer">City open data policy</a> · <a href="https://www.mississauga.ca/home/privacy-and-terms/" target="_blank" rel="noopener noreferrer">City privacy and terms</a></li></ul><p>Independent, noncommercial research candidate. Not affiliated with the City or Active Network, not survey-grade or navigational. Built with Qwen applies only to separately accepted genuine model artwork, not to these municipal overlay records. No artwork has been accepted merely by implementing this frontend.</p>${manifest.model_release?`<h3>Fresh model provenance and missing layers</h3><p>Status: ${esc(manifest.model_release.status)}. ${manifest.model_release.kind==='genuine-fresh-trained-model'?`Actual model ${esc(manifest.model_release.id)}, ${esc(manifest.model_release.optimizer_steps)} fresh optimizer updates, ${esc(manifest.model_release.dataset_pairs)} source-qualified pairs; native896 output only. Model weights are not distributed.`:'No fresh trained model/render is claimed yet. Existing teacher-reference development work is separate and never relabelled as model output.'} Every visible model tile needs exact current source/terrain/camera/native-crop and actual output review. Missing artwork remains a geographic gap; missing or rejected actor/window layers are withheld independently. Strength controls, when present, select actual reviewed images, never run inference. Ontario/CGVD2013 is a separate explicit frame, not the historical Mapzen frame.</p>`:''}`;$('info-dialog').showModal();}
